namespace InventoryApp.Services;

public class EquipmentItem
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public DateTime LastInspected { get; set; }
}

namespace InventoryApp.Services;

public class EquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate network/database latency
        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new() { Id = 1, Name = "Forklift #12",        Location = "Warehouse A",  LastInspected = new DateTime(2026, 5, 10) },
            new() { Id = 2, Name = "Conveyor Belt C3",    Location = "Warehouse B",  LastInspected = new DateTime(2026, 4, 22) },
            new() { Id = 3, Name = "Pallet Jack #7",      Location = "Loading Dock", LastInspected = new DateTime(2026, 6, 1)  },
            new() { Id = 4, Name = "Overhead Crane",      Location = "Bay 3",        LastInspected = new DateTime(2026, 3, 15) },
            new() { Id = 5, Name = "Hydraulic Press P1",  Location = "Shop Floor",   LastInspected = new DateTime(2026, 6, 20) },
            new() { Id = 6, Name = "Welding Station #4",  Location = "Shop Floor",   LastInspected = new DateTime(2026, 5, 30) },
            new() { Id = 7, Name = "Air Compressor AC-2", Location = "Utility Room", LastInspected = new DateTime(2026, 2, 18) },
            new() { Id = 8, Name = "Drill Press DP-9",    Location = "Machine Shop", LastInspected = new DateTime(2026, 6, 12) },
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@using InventoryApp.Services
@inject EquipmentService EquipmentSvc
@inject PersistentComponentState ApplicationState
@implements IDisposable

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (_items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in _items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? _items;
    private PersistingComponentStateSubscription _persistSub;

    private const string PersistKey = "equipmentItems";

    protected override async Task OnInitializedAsync()
    {
        // During the interactive render, rehydrate from persisted state
        // instead of calling the service again.
        if (ApplicationState.TryTakeFromJson<List<EquipmentItem>>(PersistKey, out var restored))
        {
            _items = restored;
        }
        else
        {
            _items = await EquipmentSvc.GetEquipmentAsync();
        }

        // During SSR, register a callback to persist the data into the page
        // so the interactive circuit can pick it up without a second fetch.
        _persistSub = ApplicationState.RegisterOnPersisting(() =>
        {
            ApplicationState.PersistAsJson(PersistKey, _items);
            return Task.CompletedTask;
        });
    }

    public void Dispose()
    {
        _persistSub.Dispose();
    }
}

